<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import {VDashboardGrid,VMetricTile,VChartTile,VActionTile,VStatusTile,VProfileTile,VProgressTile,VActivityTile,VCustomTile,VTransition,VAnimatedNumber,VReveal,useDashboardLayout} from '../src/index';
const {layout,reset}=useDashboardLayout(['revenue','signups','health','progress','chart','activity','profile','custom'],'vx-demo-dashboard');
const widgetSizes=ref<Record<string,number>>({});
try { widgetSizes.value=JSON.parse(localStorage.getItem('vx-demo-dashboard-sizes')||'{}'); } catch {}
watch(widgetSizes, v=>{try {localStorage.setItem('vx-demo-dashboard-sizes',JSON.stringify(v))} catch {}}, {deep:true});
const count=ref(24850),shown=ref(true),selected=ref('Click a point on the chart'),notice=ref('');
const tiles:Record<string,{name:string,span:number}>={revenue:{name:'Revenue',span:3},signups:{name:'Signups',span:3},health:{name:'Status',span:3},progress:{name:'Progress',span:3},chart:{name:'Activity chart',span:6},activity:{name:'Activity feed',span:6},profile:{name:'Profile',span:3},custom:{name:'Quick actions',span:3}};
const widgetOptions=Object.entries(tiles).map(([id,v])=>({id,label:v.name,span:v.span,description:`${v.name} dashboard widget`}));
const current=computed(()=>location.pathname.includes('animations')?'motion':'dashboard');
</script>
<template><main class="vx-lab"><nav class="vx-lab-nav"><a href="/">← Catalogue</a><a href="/dashboard.html">Dashboard</a><a href="/animations.html">Animations</a></nav><h1>{{current==='dashboard'?'Dashboard tiles & layouts':'Motion & transitions'}}</h1><p>Live Virexen UI components. Mobile-first, token-based and reusable across products.</p>
<template v-if="current==='dashboard'"><div class="vx-lab-toolbar"><strong>Edit mode opens automatically. Drag any widget card to rearrange; use + and − to resize</strong><button @click="reset();widgetSizes={}">Reset dashboard</button></div><VDashboardGrid v-model="layout" v-model:sizes="widgetSizes" :columns="12" editable :start-in-edit-mode="true" :available-items="widgetOptions"><template #item="{id}">
<VMetricTile v-if="id==='revenue'" title="Revenue" :value="24850" currency="GBP" :change="12.8" detail="this month"/><VMetricTile v-else-if="id==='signups'" title="Active users" :value="1284" :change="8.2" detail="this month"/>
<VStatusTile v-else-if="id==='health'" title="System health" status="healthy" description="Services operational"/><VProgressTile v-else-if="id==='progress'" title="Applications reviewed" :value="72" :total="100"/>
<VChartTile v-else-if="id==='chart'" title="Monthly activity" :points="[30,48,63,55,79,91]" :labels="['May','Jun','Jul','Aug','Sep','Oct']" @select="(i,v)=>selected=`${['May','Jun','Jul','Aug','Sep','Oct'][i]}: ${v}`"><p class="vx-lab-detail">{{selected}}</p></VChartTile>
<VActivityTile v-else-if="id==='activity'" title="Recent activity" :items="[{id:'1',title:'New registration',description:'Camper profile created',time:'10 minutes ago'},{id:'2',title:'Payment received',description:'Invoice settled',time:'1 hour ago'}]"/>
<VProfileTile v-else-if="id==='profile'" name="Alex Morgan" subtitle="Administrator"/><VCustomTile v-else title="Quick actions"><VActionTile title="Create new" description="Try the shared action button" @click="notice='Action clicked!'"/><p aria-live="polite">{{notice}}</p></VCustomTile></template></VDashboardGrid></template>
<template v-else><div class="vx-lab-toolbar"><button @click="shown=!shown">Toggle animation</button><button @click="count+=1250">Increase number</button></div><VDashboardGrid :columns="12"><div data-span style="--vx-span:4"><VCustomTile title="Animated number"><div class="vx-dash-value"><VAnimatedNumber :value="count" /></div></VCustomTile></div><div data-span style="--vx-span:4"><VTransition name="scale"><VCustomTile v-if="shown" title="Scale transition">Show and hide me.</VCustomTile></VTransition></div><div data-span style="--vx-span:4"><VReveal><VCustomTile title="Scroll reveal">Appears as it enters the viewport.</VCustomTile></VReveal></div></VDashboardGrid></template></main></template>
<style scoped>.vx-lab{max-width:1280px;margin:auto;padding:22px 18px 100px}.vx-lab-nav{display:flex;gap:20px;flex-wrap:wrap}.vx-lab-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:24px 0;flex-wrap:wrap}.vx-lab-toolbar button,.vx-tile-control button{border:1px solid var(--vx-border,#ddd);border-radius:9px;background:var(--vx-surface,#fff);padding:8px 12px;color:var(--vx-text,#17223a);cursor:pointer}.vx-tile-control{display:flex;justify-content:space-between;gap:8px;align-items:center;color:var(--vx-muted,#667);font-size:.8rem;margin-bottom:6px}.vx-tile-control button{padding:3px 8px}.vx-lab-detail{font-size:.83rem;color:var(--vx-muted,#667)}</style>
